B.aze=new A.h1("\ud83d\udcc1","\u0645\u0643\u062a\u0628\u062a\u064a \u0648\u0627\u0644\u0641\u0648\u0644\u062f\u0631\u0627\u062a","library","\u0635\u0641\u062d\u0629 \u0645\u0643\u062a\u0628\u062a\u064a \u0641\u064a\u0647\u0627 \u0643\u0644 \u0645\u062d\u0627\u0636\u0631\u0627\u062a\u0643. \u062a\u0642\u062f\u0631 \u062a\u0639\u0645\u0644 \u0641\u0648\u0644\u062f\u0631 \u0644\u0643\u0644 \u0645\u0627\u062f\u0629\u060c \u0648\u062a\u063a\u064a\u0651\u0631 \u0627\u0633\u0645\u0647 \u0648\u0644\u0648\u0646\u0647 \u0648\u0623\u064a\u0642\u0648\u0646\u062a\u0647\u060c \u0648\u062a\u0646\u0642\u0644 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0627\u062a \u062c\u0648\u0651\u0627\u0647\u060c \u0648\u062a\u0639\u0645\u0644 \u0641\u0648\u0644\u062f\u0631 \u062c\u0648\u0647 \u0641\u0648\u0644\u062f\u0631. \u0648\u0643\u0645\u0627\u0646 \u062a\u0642\u062f\u0631 \u062a\u063a\u064a\u0651\u0631 \u0634\u0643\u0644 \u0623\u064a \u0645\u062d\u0627\u0636\u0631\u0629 \u0628\u0644\u0648\u0646 \u0648\u0623\u064a\u0642\u0648\u0646\u0629. \u0644\u064a\u0647\u061f \u0644\u0645\u0627 \u0627\u0644\u0645\u0648\u0627\u062f \u062a\u0643\u062a\u0631\u060c \u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0628\u064a\u062e\u0644\u0651\u064a\u0643 \u062a\u0648\u0635\u0644 \u0644\u0623\u064a \u0645\u062d\u0627\u0636\u0631\u0629 \u0641\u064a \u062b\u0627\u0646\u064a\u0629 \u0645\u0646 \u063a\u064a\u0631 \u0645\u0627 \u062a\u062a\u0648\u0647.")
B.azk=new A.h1("\ud83d\uddfa\ufe0f","\u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0645\u0643\u062a\u0628\u0629","map","\u0632\u0631\u0627\u0631 \u0627\u0644\u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0644\u064a \u0641\u0648\u0642 \u0641\u064a \u0645\u0643\u062a\u0628\u062a\u064a \u0628\u064a\u0641\u062a\u062d\u0644\u0643 \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0643\u0644\u0647\u0627 \u0643\u0634\u062c\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0646\u0628: \u0643\u0644 \u0641\u0648\u0644\u062f\u0631 \u0648\u062c\u0648\u0651\u0627\u0647 \u0645\u062d\u0627\u0636\u0631\u0627\u062a\u0647\u060c \u0648\u062c\u0646\u0628 \u0643\u0644 \u0645\u062d\u0627\u0636\u0631\u0629 \u0625\u0646\u062a \u0642\u0631\u064a\u062a \u0645\u0646\u0647\u0627 \u0643\u0627\u0645 \u062c\u0632\u0621\u060c \u0648\u0639\u0644\u0627\u0645\u0629 \u0635\u062d \u0644\u0648 \u062e\u0644\u0651\u0635\u062a\u0647\u0627. \u0648\u0641\u064a\u0647\u0627 \u0628\u062d\u062b \u0628\u0627\u0644\u0627\u0633\u0645. \u0627\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0644\u0645\u0627 \u062a\u0628\u0642\u0649 \u0639\u0646\u062f\u0643 \u0641\u0648\u0644\u062f\u0631\u0627\u062a \u0643\u062a\u064a\u0631 \u0648\u0639\u0627\u064a\u0632 \u062a\u0646\u0637 \u0645\u0646 \u0645\u0627\u062f\u0629 \u0644\u0645\u0627\u062f\u0629 \u0628\u0633\u0631\u0639\u0629.")
B.azg=new A.h1("\ud83d\udcd6","\u062c\u0648\u0647 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629","lecture","\u0644\u0645\u0627 \u062a\u0641\u062a\u062d \u0623\u064a \u0645\u062d\u0627\u0636\u0631\u0629\u060c \u0647\u062a\u0644\u0627\u0642\u064a \u0641\u0648\u0642 \u0623\u0631\u0628\u0639 \u062a\u0627\u0628\u0627\u062a: \u0627\u0644\u0634\u0631\u062d\u060c \u0648\u0627\u0644\u062e\u0644\u0627\u0635\u0629\u060c \u0648\u0627\u0644\u0623\u0645\u062b\u0644\u0629 \u0623\u0648 \u0627\u0644\u0627\u0642\u062a\u0628\u0627\u0633\u0627\u062a\u060c \u0648\u0627\u0644\u0643\u0648\u064a\u0632. \u0641\u064a \u062a\u0627\u0628 \u0627\u0644\u0634\u0631\u062d \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0645\u062a\u0642\u0633\u0651\u0645\u0629 \u0644\u0623\u062c\u0632\u0627\u0621 \u0635\u063a\u064a\u0631\u0629\u060c \u0648\u0643\u0644 \u062c\u0632\u0621 \u0628\u062a\u062e\u0644\u0651\u0635\u0647 \u0628\u064a\u062a\u0639\u0644\u0651\u0645 \u0639\u0644\u064a\u0647 \u0628\u0639\u0644\u0627\u0645\u0629 \u0635\u062d \u062e\u0636\u0631\u0627. \u0644\u064a\u0647 \u0623\u062c\u0632\u0627\u0621\u061f \u0639\u0634\u0627\u0646 \u0627\u0644\u0645\u0630\u0627\u0643\u0631\u0629 \u0639\u0644\u0649 \u062f\u0641\u0639\u0627\u062a \u0635\u063a\u064a\u0631\u0629 \u0628\u062a\u062a\u0641\u0647\u0645 \u0648\u0628\u062a\u062a\u062d\u0641\u0638 \u0623\u062d\u0633\u0646\u060c \u0648\u062a\u0642\u062f\u0631 \u062a\u0648\u0642\u0641 \u0648\u062a\u0631\u062c\u0639 \u0641\u064a \u0623\u064a \u0648\u0642\u062a.")
B.azs=new A.h1("\ud83d\udcdd","\u0642\u0631\u0627\u064a\u0629 \u0627\u0644\u062c\u0632\u0621","section","\u062c\u0648\u0647 \u0627\u0644\u062c\u0632\u0621\u060c \u0627\u0644\u0643\u0644\u0627\u0645 \u0645\u0634\u0631\u0648\u062d \u0628\u0628\u0633\u0627\u0637\u0629\u060c \u0648\u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0627\u0644\u0645\u0647\u0645\u0629 \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a \u0645\u062a\u0644\u0648\u0651\u0646\u0629 \u0639\u0634\u0627\u0646 \u062a\u062d\u0641\u0638\u0647\u0627 \u0632\u064a \u0645\u0627 \u0647\u062a\u064a\u062c\u064a \u0641\u064a \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646. \u062a\u062d\u062a \u0639\u0646\u062f\u0643 \u0627\u0644\u062a\u0627\u0644\u064a \u0648\u0627\u0644\u0633\u0627\u0628\u0642\u060c \u0648\u0627\u0644\u0646\u0642\u0637 \u0628\u062a\u0648\u0631\u064a\u0643 \u0625\u0646\u062a \u0641\u064a \u0623\u0646\u0647\u064a \u062c\u0632\u0621. \u0648\u0644\u0648 \u062c\u0632\u0621 \u0645\u0634 \u0639\u0627\u062c\u0628\u0643 \u0623\u0648 \u0645\u0634 \u0641\u0627\u0647\u0645\u0647\u060c \u062f\u0648\u0633 \u0639\u0644\u0649 \u0632\u0631\u0627\u0631 \u0627\u0644\u0639\u0635\u0627\u064a\u0629 \u0627\u0644\u0633\u062d\u0631\u064a\u0629\u060c \u0648\u0627\u0643\u062a\u0628 \u0639\u0627\u064a\u0632 \u062a\u062d\u0633\u0651\u0646 \u0625\u064a\u0647\u060c \u0648\u0627\u0644\u0640 AI \u0647\u064a\u0639\u064a\u062f \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062c\u0632\u0621 \u062f\u0647 \u0628\u0633.")
B.azd=new A.h1("\ud83d\udd0a","\u0627\u0633\u0645\u0639 \u0628\u062f\u0644 \u0645\u0627 \u062a\u0642\u0631\u0627","section","\u0632\u0631\u0627\u0631 \u0627\u0644\u0633\u0645\u0627\u0639\u0629 \u062c\u0646\u0628 \u0639\u0646\u0648\u0627\u0646 \u0623\u064a \u062c\u0632\u0621 \u0628\u064a\u0642\u0631\u0627\u0644\u0643 \u0627\u0644\u0635\u0641\u062d\u0629 \u0628\u0635\u0648\u062a\u060c \u0648\u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0644\u064a \u0628\u062a\u062a\u0642\u0627\u0644 \u0628\u062a\u0646\u0648\u0651\u0631 \u0642\u062f\u0627\u0645\u0643 \u0639\u0634\u0627\u0646 \u062a\u062a\u0627\u0628\u0639. \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0634\u063a\u064a\u0644 \u062a\u062e\u062a\u0627\u0631 \u0627\u0644\u0635\u0648\u062a\u060c \u0635\u0648\u062a \u0627\u0644\u0640 AI \u0627\u0644\u0645\u0635\u0631\u064a \u0623\u0648 \u0635\u0648\u062a \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u0648\u062a\u0633\u0631\u0651\u0639 \u0623\u0648 \u062a\u0628\u0637\u0651\u0623\u060c \u0648\u062a\u0646\u0637 \u0644\u0644\u0641\u0642\u0631\u0629 \u0627\u0644\u0644\u064a \u0628\u0639\u062f\u0647\u0627. \u0648\u0644\u0648 \u062f\u0648\u0633\u062a \u062f\u0648\u0633\u0629 \u0637\u0648\u064a\u0644\u0629 \u0639\u0644\u0649 \u0623\u064a \u0643\u0644\u0645\u0629\u060c \u0623\u0648 \u062f\u0628\u0644 \u0643\u0644\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631\u060c \u0647\u064a\u0637\u0644\u0639\u0644\u0643 \u0645\u0639\u0646\u0627\u0647\u0627\u060c \u0648\u062a\u0642\u062f\u0631 \u062a\u0633\u0645\u0639 \u0646\u0637\u0642\u0647\u0627 \u0623\u0648 \u062a\u0642\u0631\u0627 \u0645\u0646 \u0639\u0646\u062f\u0647\u0627. \u062f\u0647 \u0645\u0641\u064a\u062f \u062c\u062f\u0627\u064b \u0648\u0625\u0646\u062a \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0635\u0644\u0627\u062a\u060c \u0623\u0648 \u0644\u0645\u0627 \u0639\u064a\u0646\u0643 \u062a\u062a\u0639\u0628\u060c \u0623\u0648 \u0644\u0648 \u0628\u062a\u062d\u0628 \u062a\u0630\u0627\u0643\u0631 \u0628\u0648\u062f\u0646\u0643.")
B.azt=new A.h1("\u2b50","\u0627\u0644\u062e\u0644\u0627\u0635\u0629","sheet","\u062a\u0627\u0628 \u0627\u0644\u062e\u0644\u0627\u0635\u0629 \u0641\u064a\u0647 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0643\u0644\u0647\u0627 \u0641\u064a \u0648\u0631\u0642\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u062e\u062a\u0635\u0631\u0629. \u062f\u064a \u0645\u062b\u0627\u0644\u064a\u0629 \u0644\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0644\u064a\u0644\u0629 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u060c \u0623\u0648 \u0642\u0628\u0644 \u0645\u0627 \u062a\u062f\u062e\u0644 \u0627\u0644\u0644\u062c\u0646\u0629 \u0628\u0631\u0628\u0639 \u0633\u0627\u0639\u0629. \u0646\u0635\u064a\u062d\u0629: \u0630\u0627\u0643\u0631 \u0645\u0646 \u0627\u0644\u0634\u0631\u062d \u0627\u0644\u0623\u0648\u0644\u060c \u0648\u0628\u0639\u062f\u064a\u0646 \u0631\u0627\u062c\u0639 \u0645\u0646 \u0627\u0644\u062e\u0644\u0627\u0635\u0629\u060c \u0639\u0634\u0627\u0646 \u062a\u062b\u0628\u0651\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0641\u064a \u062f\u0645\u0627\u063a\u0643.")
B.azf=new A.h1("\ud83d\udcac","\u0627\u0644\u0623\u0645\u062b\u0644\u0629 \u0648\u0627\u0644\u0627\u0642\u062a\u0628\u0627\u0633\u0627\u062a","quotes","\u0627\u0644\u062a\u0627\u0628 \u0627\u0644\u062a\u0627\u0644\u062a \u0641\u064a\u0647 \u0627\u0644\u062c\u0645\u0644 \u0648\u0627\u0644\u062a\u0639\u0631\u064a\u0641\u0627\u062a \u0627\u0644\u0645\u0647\u0645\u0629 \u0645\u0646 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0632\u064a \u0645\u0627 \u0647\u064a\u060c \u0623\u0648 \u0623\u0645\u062b\u0644\u0629 \u0648\u0623\u0633\u0626\u0644\u0629 \u0644\u0648 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0645\u0639\u0645\u0648\u0644\u0629 \u0628\u0627\u0644\u0640 AI. \u0627\u0633\u062a\u062e\u062f\u0645\u0647 \u0639\u0634\u0627\u0646 \u062a\u062d\u0641\u0638 \u0627\u0644\u062a\u0639\u0631\u064a\u0641\u0627\u062a \u0628\u0627\u0644\u0646\u0635 \u0627\u0644\u0644\u064a \u0627\u0644\u062f\u0643\u062a\u0648\u0631 \u0643\u0627\u062a\u0628\u0647\u060c \u0644\u0623\u0646 \u062f\u064a \u0627\u0644\u0644\u064a \u0628\u062a\u064a\u062c\u064a \u0641\u064a \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0643\u062a\u064a\u0631.")
B.azq=new A.h1("\ud83c\udfae","\u0627\u0644\u0643\u0648\u064a\u0632","quiztab","\u062a\u0627\u0628 \u0627\u0644\u0643\u0648\u064a\u0632 \u0641\u064a\u0647 \u0623\u0633\u0626\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629. \u062a\u0642\u062f\u0631 \u062a\u062e\u062a\u0627\u0631 \u0646\u0648\u0639 \u0627\u0644\u0623\u0633\u0626\u0644\u0629\u060c \u0623\u0648 \u062a\u062d\u0644 \u0627\u0644\u0643\u0644. \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u064a\u062d\u0641\u0638 \u0623\u0639\u0644\u0649 \u062f\u0631\u062c\u0629 \u062c\u0628\u062a\u0647\u0627. \u0648\u0644\u0645\u0627 \u062a\u062e\u0644\u0651\u0635\u060c \u062a\u0642\u062f\u0631 \u062a\u0639\u064a\u062f \u0627\u0644\u063a\u0644\u0637 \u0628\u0633\u060c \u0623\u0648 \u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0644\u064a \u063a\u0644\u0637\u062a \u0641\u064a\u0647\u0627\u060c \u0623\u0648 \u062a\u0635\u0641\u0651\u0631 \u0627\u0644\u062f\u0631\u062c\u0629 \u0648\u062a\u0628\u062f\u0623 \u0645\u0646 \u0627\u0644\u0623\u0648\u0644. \u0644\u064a\u0647 \u0627\u0644\u0643\u0648\u064a\u0632 \u0645\u0647\u0645\u061f \u0644\u0623\u0646\u0643 \u0644\u0645\u0627 \u062a\u062e\u062a\u0628\u0631 \u0646\u0641\u0633\u0643 \u0628\u062a\u0639\u0631\u0641 \u0625\u0646\u062a \u0641\u0627\u0647\u0645 \u0625\u064a\u0647 \u0641\u0639\u0644\u0627\u064b\u060c \u0648\u0625\u064a\u0647 \u0627\u0644\u0644\u064a \u0645\u062d\u062a\u0627\u062c \u062a\u0631\u062c\u0639\u0644\u0647.")
B.azi=new A.h1("\u2705","\u062d\u0644 \u0627\u0644\u0623\u0633\u0626\u0644\u0629","quiz","\u0648\u0625\u0646\u062a \u0628\u062a\u062d\u0644\u060c \u0647\u062a\u0634\u0648\u0641 \u0631\u0642\u0645 \u0627\u0644\u0633\u0624\u0627\u0644\u060c \u0648\u0639\u062f\u062f \u0625\u062c\u0627\u0628\u0627\u062a\u0643 \u0627\u0644\u0635\u062d \u0641\u0648\u0642. \u0628\u0639\u062f \u0643\u0644 \u0625\u062c\u0627\u0628\u0629 \u0647\u062a\u0639\u0631\u0641 \u0639\u0644\u0649 \u0637\u0648\u0644 \u0635\u062d \u0648\u0644\u0627 \u063a\u0644\u0637\u060c \u0648\u0644\u064a\u0647. \u0645\u062a\u0642\u0644\u0642\u0634 \u0645\u0646 \u0627\u0644\u063a\u0644\u0637\u060c \u062f\u0647 \u0623\u062d\u0633\u0646 \u0648\u0642\u062a \u062a\u063a\u0644\u0637 \u0641\u064a\u0647\u060c \u0642\u0628\u0644 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0645\u0634 \u062c\u0648\u0627\u0647.")
B.azl=new A.h1("\ud83d\udd0d","\u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0643\u0644 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0627\u062a","search","\u0632\u0631\u0627\u0631 \u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0628\u064a\u062f\u0648\u0651\u0631 \u0641\u064a \u0643\u0644 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0627\u062a \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629. \u0627\u0643\u062a\u0628 \u0623\u064a \u0643\u0644\u0645\u0629\u060c \u0628\u0627\u0644\u0639\u0631\u0628\u064a \u0623\u0648 \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u060c \u0648\u0647\u064a\u0637\u0644\u0639\u0644\u0643 \u0643\u0644 \u0645\u0643\u0627\u0646 \u0627\u062a\u0630\u0643\u0631\u062a \u0641\u064a\u0647\u060c \u0648\u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u062a\u0644\u0648\u0651\u0646\u0629. \u062f\u0648\u0633 \u0639\u0644\u0649 \u0623\u064a \u0646\u062a\u064a\u062c\u0629 \u0648\u0647\u064a\u0641\u062a\u062d\u0644\u0643 \u0627\u0644\u062c\u0632\u0621 \u062f\u0647 \u0628\u0627\u0644\u0638\u0628\u0637. \u062f\u0647 \u0628\u064a\u0648\u0641\u0651\u0631 \u0639\u0644\u064a\u0643 \u0648\u0642\u062a \u0643\u0628\u064a\u0631 \u0644\u0645\u0627 \u062a\u0643\u0648\u0646 \u0641\u0627\u0643\u0631 \u0645\u0635\u0637\u0644\u062d \u0648\u0645\u0634 \u0641\u0627\u0643\u0631 \u0647\u0648 \u0641\u064a \u0623\u0646\u0647\u064a \u0645\u062d\u0627\u0636\u0631\u0629.")
B.azc=new A.h1("\ud83e\udd16","\u0627\u0644\u0645\u0633\u0627\u0639\u062f","assistant","\u0635\u0641\u062d\u0629 \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u062f\u064a \u0645\u062f\u0631\u0651\u0633\u0643 \u0627\u0644\u062e\u0635\u0648\u0635\u064a. \u0627\u0633\u0623\u0644\u0647 \u0623\u064a \u0633\u0624\u0627\u0644: \u0627\u0634\u0631\u062d\u0644\u064a \u0627\u0644\u062c\u0632\u0621 \u062f\u0647 \u0628\u0645\u062b\u0627\u0644\u060c \u0627\u0639\u0645\u0644\u064a \u0623\u0633\u0626\u0644\u0629\u060c \u0644\u062e\u0651\u0635\u0644\u064a\u060c \u0623\u0648 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627. \u062a\u0642\u062f\u0631 \u062a\u0628\u0639\u062a\u0644\u0647 \u0635\u0648\u0631\u0629 \u0623\u0648 \u0645\u0644\u0641\u060c \u0623\u0648 \u062a\u062a\u0643\u0644\u0645 \u0628\u0635\u0648\u062a\u0643 \u0645\u0646 \u0632\u0631\u0627\u0631 \u0627\u0644\u0645\u0627\u064a\u0643 \u0628\u062f\u0644 \u0627\u0644\u0643\u062a\u0627\u0628\u0629. \u0648\u0644\u0648 \u0627\u0644\u0631\u062f \u0637\u0648\u0651\u0644 \u0623\u0648 \u0645\u0634 \u0647\u0648 \u0627\u0644\u0644\u064a \u0639\u0627\u064a\u0632\u0647\u060c \u0627\u0644\u0632\u0631\u0627\u0631 \u0628\u064a\u0628\u0642\u0649 \u0623\u062d\u0645\u0631 \u0648\u0625\u0646\u062a \u0645\u0633\u062a\u0646\u064a\u060c \u062f\u0648\u0633 \u0639\u0644\u064a\u0647 \u0648\u0627\u0644\u0631\u062f \u064a\u0642\u0641 \u0641\u0648\u0631\u0627\u064b. \u0648\u0645\u0646 \u0627\u0644\u0632\u0631\u0627\u0631 \u0627\u0644\u0644\u064a \u0641\u0648\u0642 \u062a\u062e\u062a\u0627\u0631 \u0623\u0646\u0647\u064a AI \u064a\u0631\u062f \u0639\u0644\u064a\u0643. \u0648\u0643\u0645\u0627\u0646 \u0632\u0631\u0627\u0631 \u0627\u0644\u0631\u0648\u0628\u0648\u062a \u0627\u0644\u0639\u0627\u064a\u0645 \u062c\u0648\u0647 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0627\u062a \u0628\u064a\u0641\u062a\u062d \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0648\u0647\u0648 \u0634\u0627\u064a\u0641 \u0625\u0646\u062a \u0628\u062a\u0642\u0631\u0627 \u0625\u064a\u0647\u060c \u0641\u062a\u0633\u0623\u0644\u0647 \u0639\u0646 \u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0644\u064a \u0642\u062f\u0627\u0645\u0643 \u0639\u0644\u0649 \u0637\u0648\u0644.")
